mapper.select:
select t.finprod_id finprodId,t.share_amt shareAmt,t.yield,t.ps from trd_product_deal t left JOIN trd_product_deal_add tpda on t.TRADE_ID=tpda.TRADE_ID left JOIN fin_product_type fpt on t.finprod_id=fpt.finprod_id and t.branch=fpt.branch where t.finprod_id=#{finprodId}
AND tpda.PORTFOLIO_ID IN
#{item}
and STR_TO_DATE(#{date},'%Y-%m-%d')=t.TRADE_DATE and fpt.type_8='F01'and t.trade_status='01'and t.is_cancel='N' and t.ps in('T01','T02') order by t.UPDATE_TIME asc

select t.pos_amount posAmount ,t.cost_rate costRate,t.FAIRE_PRICE fairePrice from  ASSET_TARGET_DB  t  where t.cdate=STR_TO_DATE(#{date},'%Y-%m-%d')
and t.finprod_id=#{finprodId}

    and t.IS_PERNE= #{pass}

and LIMIT=1

mapper.insert:
insert into PTL_SEC_POSITION (PORTFOLIO_ID, SEC_ACCT_ID, FINPROD_ID, BRANCH, HODING_TYPE, CDATE, AMOUNT, CCY, FACE_VALUE, P_FINPROD_ID, INV_AIM, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME ) SELECT targetTable.PORTFOLIO_ID, targetTable.SEC_ACCT_ID, targetTable.FINPROD_ID, targetTable.BRANCH, targetTable.HODING_TYPE, #{batchDate,jdbcType=DATE}, SUM(targetTable.AMOUNT), targetTable.CCY, null, null, targetTable.INV_AIM, 'system', null, NOW(), 'system', NOW() FROM ( SELECT PORTFOLIO_ID, IFNULL(SEC_ACCT_ID, '999999') as SEC_ACCT_ID, FINPROD_ID, BRANCH, AMOUNT, CCY, IFNULL(INV_AIM, '999999') as INV_AIM, HODING_TYPE FROM PTL_SEC_POSITION WHERE HODING_TYPE != #{POSITION_TYPE_01,jdbcType=VARCHAR} and CDATE = #{lastDate,jdbcType=DATE}
and (
)
union all SELECT PORTFOLIO_ID, IFNULL(SEC_ACCT_ID, '999999') as SEC_ACCT_ID, FINPROD_ID, BRANCH, sum(AMOUNT) as AMOUNT, CCY, IFNULL(INV_AIM, '999999') as INV_AIM, HODING_TYPE FROM PTL_SEC_POSITION_FLOW WHERE HODING_TYPE != #{POSITION_TYPE_01,jdbcType=VARCHAR} and CDATE = #{batchDate,jdbcType=DATE}
and (
)
GROUP BY PORTFOLIO_ID, IFNULL(SEC_ACCT_ID, '999999'), FINPROD_ID, BRANCH, CCY, IFNULL(INV_AIM, '999999'), HODING_TYPE ) targetTable group by targetTable.PORTFOLIO_ID, targetTable.SEC_ACCT_ID, targetTable.FINPROD_ID, targetTable.BRANCH, targetTable.HODING_TYPE, targetTable.CCY, targetTable.INV_AIM
